<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { formatDateOnly } from '@/Support/dateOnly';
import { Head, Link, useForm } from '@inertiajs/vue3';
const props=defineProps<{entry:any;can_manage:boolean}>();const form=useForm({teacher_feedback:props.entry.teacher_feedback||''});const save=()=>form.patch(route('creative-writing.feedback',props.entry.id),{preserveScroll:true});
</script>
<template><Head :title="entry.title"/><AuthenticatedLayout><Link :href="route('creative-writing.index')">← Journal history</Link><header class="mt-3"><p class="text-uppercase small fw-bold text-secondary mb-1">{{ entry.student }} · {{ formatDateOnly(entry.date) }}</p><h1>{{ entry.title }}</h1><p><span class="badge text-bg-info text-capitalize">{{ entry.status.replace('_',' ') }}</span> · {{ entry.word_count }} words · {{ entry.school_year }}</p></header><div class="row g-4 mt-1"><div class="col-lg-5"><section class="card"><div class="card-body"><p v-if="entry.category" class="small text-uppercase fw-bold text-primary">{{ entry.category }}</p><h2 class="h5">Assigned prompt</h2><p class="lead">{{ entry.prompt }}</p><h3 class="h6">Include:</h3><ul><li v-for="hint in entry.include_hints" :key="hint">{{ hint }}</li></ul><p class="small text-secondary mb-0">This is the historical snapshot assigned on {{ formatDateOnly(entry.date) }}.</p></div></section><section class="card mt-3"><div class="card-body"><h2 class="h5">Timeline</h2><dl><dt>Assigned</dt><dd>{{ entry.assigned_at||'—' }}</dd><dt>Started</dt><dd>{{ entry.started_at||'—' }}</dd><dt>Last saved</dt><dd>{{ entry.last_saved_at||'—' }}</dd><dt>Submitted</dt><dd>{{ entry.submitted_at||'—' }}</dd></dl></div></section></div><div class="col-lg-7"><section class="response card"><div class="card-body"><h2 class="h5">Student response</h2><p v-if="entry.response">{{ entry.response }}</p><p v-else class="text-secondary">The student has not started writing yet.</p></div></section><form v-if="can_manage" class="card mt-3" @submit.prevent="save"><div class="card-body"><h2 class="h5">Supportive feedback</h2><label class="form-label" for="feedback">Teacher/parent note</label><textarea id="feedback" v-model="form.teacher_feedback" class="form-control" rows="5"/><p v-if="form.errors.teacher_feedback" class="text-danger" role="alert">{{ form.errors.teacher_feedback }}</p><button class="btn btn-primary mt-3" :disabled="form.processing"